/// `RouteOut` is the callback type for routing `CollateralInquiryAck` messages.
pub type RouteOut = fn(msg: CollateralInquiryAck, session_id: SessionID) -> Result<(), MessageRejectErrorEnum>;

/// Route type returned by the `route` function.
pub type Route = (&'static str, &'static str, Box<dyn Fn(&Message, SessionID) -> Result<(), MessageRejectErrorEnum> + Send>);

/// Returns the begin string, message type, and route function for `CollateralInquiryAck`.
pub fn route(router: RouteOut) -> Route {
    let r = move |msg: &Message, session_id: SessionID| -> Result<(), MessageRejectErrorEnum> {
        router(CollateralInquiryAck::from_message(msg.clone()), session_id)
    };
    ("FIX.4.4", "BG", Box::new(r))
}
